/**
 * @pathland/view
 * 
 * Pathland View Framework - Reactive, declarative UI for Pathland protocol.
 * 
 * This package provides a component-based, Angular-like API for building UI
 * that compiles to Pathland's binary protocol. It features fine-grained reactivity
 * where only changed properties generate update commands.
 * 
 * @example
 * ```typescript
 * import { VStack, HStack, Text, signal, initialRender } from '@pathland/view';
 * import { PostMessageTransport } from '@pathland/transport';
 * 
 * class App {
 *   count = signal(0);
 *   
 *   createView() {
 *     return VStack(
 *       Text(this.count.map(n => `Count: ${n}`)),
 *       HStack(
 *         Text("+"),
 *         Text("-")
 *       ).tapGesture(() => this.count.set(this.count.get() + 1))
 *     );
 *   }
 * }
 * 
 * const app = new App();
 * const transport = new PostMessageTransport(iframe.contentWindow);
 * initialRender(app.createView(), transport);
 * ```
 */

// Re-export core types and functions
export type { Modifier, GestureSpec } from './view-node';
export { ViewNode, resetNodeIdCounter } from './view-node';
export { View } from './view';
export { Signal, signal, commandQueue } from './signal';
export { VStack, HStack, Text } from './components';
export { initialRender, handleDispatchEvent, handleGestureUpdate, getConditionalParent } from './renderer';
export { propertyNameToId, compilePropertyValue } from './utils';

// Lifecycle gesture builders (SwiftUI-style)
export { Gesture, TapGesture, LongPressGesture, DragGesture } from './gestures';
export type { GestureValue, GestureHandlers } from './gestures';

// Re-export control flow functions
export { If, For, Switch } from './control-flow';
export type { ForRenderFn, SwitchCaseValue, SwitchCaseHandler, SwitchCases } from './control-flow';

// Chainable methods are added to ViewNode.prototype in view-node.ts
// Available on any ViewNode:
// - .padding(value: number): ViewNode
// - .background(color: string | number): ViewNode
// - .color(color: string | number): ViewNode
// - .fontSize(value: number): ViewNode
// - .fontWeight(value: number): ViewNode
// - .margin(value: number): ViewNode
// - .gap(value: number): ViewNode
// - .spacing(value: number): ViewNode (alias for gap)
// - .opacity(value: number): ViewNode
// - .visible(value: boolean | Signal<boolean>): ViewNode
// - .tapGesture(handler: () => void): ViewNode
// - .longPressGesture(handler: () => void): ViewNode

/**
 * @pathland/view - Component Factories
 * 
 * Factory functions for creating Pathland ViewNodes.
 * These are the core building blocks for creating UI.
 */

import { ViewNode } from './view-node';
import { Signal } from './signal';

// ============================================
// CORE COMPONENTS
// ============================================

/**
 * Create a vertical stack layout component.
 * 
 * @param children Child nodes to stack vertically
 * @returns A VStack ViewNode
 * 
 * @example
 * ```typescript
 * VStack(
 *   Text("Item 1"),
 *   Text("Item 2"),
 *   Text("Item 3")
 * ).spacing(8).padding(16)
 * ```
 */
export function VStack(...children: ViewNode[]): ViewNode {
  return new ViewNode('VStack', children);
}

/**
 * Create a horizontal stack layout component.
 * 
 * @param children Child nodes to stack horizontally
 * @returns An HStack ViewNode
 * 
 * @example
 * ```typescript
 * HStack(
 *   Text("Left"),
 *   Text("Right")
 * ).spacing(8).padding(16)
 * ```
 */
export function HStack(...children: ViewNode[]): ViewNode {
  return new ViewNode('HStack', children);
}

/**
 * Create a text component.
 * 
 * @param content The text content (string or signal)
 * @returns A Text ViewNode
 * 
 * @example
 * ```typescript
 * // Static text
 * Text("Hello World")
 * 
 * // Dynamic text with signal
 * const count = signal(0);
 * Text(count.map(n => `Count: ${n}`))
 * 
 * // With modifiers
 * Text("Title").fontSize(24).color("primary")
 * ```
 */
=====VIEW-NODE=====
/**
 * @pathland/view - ViewNode
 * 
 * Immutable node in the virtual UI tree with stable identity.
 * Each ViewNode has a unique nodeId that never changes for its lifetime.
 */

import type { PropertyValue } from '@pathland/protocol';
import { Signal, commandQueue } from './signal';
import { propertyNameToId, compilePropertyValue } from './utils';
import { getConditionalParent } from './renderer';
import { TapGesture, LongPressGesture } from './gestures';
import type { Gesture } from './gestures';

// Local component type constants (avoid protocol import to prevent circular dependency)
const COMPONENT_TYPES = {
  VSTACK: 0x0002,
  HSTACK: 0x0001,
  TEXT: 0x0003,
  BUTTON: 0x0004,
  SPACER: 0x0008,
  IMAGE: 0x0005,
  SCROLLVIEW: 0x0009,
  LIST: 0x000A,
  GRID: 0x000B,
  SWITCH: 0x0006,
  TEXT_FIELD: 0x0007,
} as const;


// ============================================
// TYPES
// ============================================

/**
 * A modifier that can be applied to a ViewNode.
 * Modifiers represent styling or behavior changes.
 */
interface Modifier {
  kind: string;
  [key: string]: any;
}

/**
 * A discrete gesture registration (kind + handler), mapped to a single event
 * type (e.g. tap -> CLICK). Lifecycle gestures use the `Gesture` class instead.
 */
export interface GestureSpec {
  kind: string;
  handler: () => void;
  [key: string]: any;
}

// ============================================
// NODE ID COUNTER
// ============================================

/**
 * Global counter for assigning unique node IDs.
 */
let nodeIdCounter = 0;

/**
 * Reset node ID counter (useful for testing).
 */
export function resetNodeIdCounter(): void {
  nodeIdCounter = 0;
}

// ============================================
// VIEW NODE CLASS
// ============================================

/**
 * A node in the virtual UI tree.
 */
export class ViewNode {
  type: string;
  children: ViewNode[];
  modifiers: Modifier[];
  gestures: GestureSpec[];
  attachedGestures: Gesture[];
  properties: Record<string, any>;
  nodeId: number;

  constructor(
    type: string,
    children: ViewNode[] = [],
    properties: Record<string, any> = {},
    modifiers: Modifier[] = [],
    gestures: GestureSpec[] = [],
    attachedGestures: Gesture[] = []
  ) {
    this.type = type;
    this.children = children;
    this.properties = { ...properties };
    this.modifiers = [...modifiers];
    this.gestures = [...gestures];
    this.attachedGestures = [...attachedGestures];
    this.nodeId = ++nodeIdCounter;

